"""Reproducible prepared-copy run. Does not pretend to call an LLM."""
import engine as e
def block(headline,body,ids): return dict(headline=headline,body=body,claim_ids=ids)
def claim(source,id,text,fragment,population,limitations,section='Abstract'):
    for p in source['pages']:
        if fragment in p['text']: return dict(id=id,text=text,quote=fragment,page=p['page'],section=section,population=population,limitations=limitations)
    raise ValueError('Prepared quote absent: '+fragment)
def resistance():
    s=e.ingest(e.ROOT/'sources/resistance-review.pdf')
    limitations='Adults aged 18–65 with overweight or obesity. Moderate certainty for fat-free mass; effects are group averages, not individual guarantees.'
    claims=[claim(s,'C1','Adding resistance exercise helped limit fat-free mass loss during dietary weight loss.','loss of fat- free mass (between- group standardised mean difference (SMD): 0.40, p=0.0003, moderate certainty)','Adults aged 18–65 with overweight or obesity',limitations),claim(s,'C2','The review included 25 trials.','searches yielded N=6934 studies of which n=25 were relevant for inclusion after screening for eligibility.','Adults aged 18–65 with BMI ≥25','The trials differed in their interventions and populations.')]
    cards=[block('Keep strength in the conversation.','What would you like your weight-management plan to make room for?',[]),block('What did researchers study?','A review included 25 trials of dietary weight loss, comparing plans with and without resistance exercise.',['C2']),block('A finding worth discussing.','Adding resistance exercise helped limit loss of fat-free mass. The certainty of this evidence was moderate.',['C1']),block('Keep the context close.','The evidence concerns adults aged 18–65 with overweight or obesity. It cannot promise your individual result.',['C1']),block('Built around your real week.','Between work, chai breaks and family dinners: what could fit? Bring that question to your care team.',[])]
    pack=dict(title='Strength belongs in the conversation',study_design='Systematic review and meta-analysis of randomised trials',limitations=[limitations],claims=claims,carousel=cards,static=block('Make room for strength.','During dietary weight loss, resistance exercise helped limit fat-free mass loss. Moderate-certainty evidence in adults with overweight or obesity.',['C1']),reel=[block('A question beyond the scale.','What could strength look like in your week?',[]),block('A useful finding.','In a review of dietary weight-loss trials, resistance exercise helped limit fat-free mass loss.',['C1']),block('Evidence with limits.','Certainty was moderate. Participants were adults aged 18–65 with overweight or obesity. Your results may differ.',['C1']),block('Bring your real life.','Desk days. Family dinners. Your starting point. Ask your care team what fits.',[])],caption='A question for your next care conversation: where does strength fit? A review found that adding resistance exercise during dietary weight loss helped limit fat-free mass loss, with moderate certainty. The evidence concerned adults aged 18–65 with overweight or obesity. Individual results vary.',caption_claim_ids=['C1'],hashtags=['#SteerClub','#MetabolicHealth','#Strength'],message='Ask about strength as part of weight management.',reasoning='A specific finding and its limits make a practical conversation starter without promising weight loss.',provenance=dict(mode='prepared_ai_assisted_copy',model='authored in Codex; no runtime API call',source_url='https://doi.org/10.1136/bmjsem-2024-002363'))
    e.save_pack(s['id'],pack);e.render(s['id']);return s['id']
def india():
    s=e.ingest(e.ROOT/'IJDDT,Vol16,Issue29s,Article16.pdf')
    limits='Small before-and-after intervention subgroup; no randomised comparator described. Table IV reports 8/30 as 25%, which is inconsistent. Intervention duration is unclear. Do not use effect estimates in promotional copy.'
    cs=[claim(s,'C1','100 men were recruited, but the intervention subgroup contained 30 men.','Among 100 obese men, a subsample of 30 patients with MetS received personalized counseling, pamphlets, and PowerPoint presentations','Men aged 36–55 in Coimbatore',limits,'Methods 2.4'),claim(s,'C2','Outcomes were assessed before and after the intervention.','The effectiveness of the program was evaluated by comparing outcomes before and after the intervention.','Intervention subgroup of 30 men',limits)]
    cards=[block('Read beyond the headline.','A research number can sound simple. Its context matters.',['C1']),block('100 recruited. 30 in the programme.','This Coimbatore paper describes a smaller intervention subgroup than its total recruited sample.',['C1']),block('Before and after.','The paper compared outcomes before and after its programme. This design alone cannot isolate the cause of a change.',['C2']),block('Questions worth asking.','Who took part? How was change assessed? What remains uncertain?',[]),block('Bring the paper.','Ask your doctor to help interpret the evidence for your own situation.',[])]
    pack=dict(title='Read beyond the headline',study_design='Before-and-after nutrition intervention; small subgroup',limitations=[limits],claims=cs,carousel=cards,static=cards[1],reel=[cards[0],cards[1],cards[2],cards[4]],caption='Before sharing a study, check who actually received the intervention. This Coimbatore paper recruited 100 men but describes an intervention subgroup of 30. Its before-and-after comparison needs careful interpretation. Bring your questions to a clinician.',caption_claim_ids=['C1','C2'],hashtags=['#SteerClub','#ResearchLiteracy'],message='Understand the sample and study design before trusting a headline.',reasoning='Demonstrates that the pipeline exposes evidence limitations instead of converting every result into a benefit claim.',provenance=dict(mode='prepared_ai_assisted_copy',model='authored in Codex; no runtime API call',source_url='https://doi.org/10.25258/ijddt.16.29s.16'))
    e.save_pack(s['id'],pack);e.render(s['id']);return s['id']
if __name__=='__main__':
    results=dict(resistance=resistance(),india=india()); e.write(e.ROOT/'sample-runs.json',results);print(results)
